@typeparam TItem
@implements IAsyncDisposable

<div class="infinite-scroll-container">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div @ref="_sentinelRef" class="infinite-scroll-sentinel">
            @if (_isLoading)
            {
                <div class="infinite-scroll-spinner" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            }
        </div>
    }
</div>

using Microsoft.AspNetCore.Components;
using Microsoft.JSInterop;

namespace sv_70bac84e98914f18a8d5352d656f2be1.Components;

public partial class InfiniteScrollList<TItem> : IAsyncDisposable
{
    [Parameter, EditorRequired]
    public required IReadOnlyList<TItem> Items { get; set; }

    [Parameter, EditorRequired]
    public required RenderFragment<TItem> ChildContent { get; set; }

    [Parameter, EditorRequired]
    public required EventCallback OnLoadMore { get; set; }

    [Parameter]
    public bool HasMore { get; set; }

    [Inject]
    private IJSRuntime JS { get; set; } = default!;

    private ElementReference _sentinelRef;
    private IJSObjectReference? _module;
    private IJSObjectReference? _observer;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? _dotNetRef;
    private bool _isLoading;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/InfiniteScrollList.razor.js");
            _dotNetRef = DotNetObjectReference.Create(this);
        }

        // (Re)attach observer whenever HasMore is true and we have a module ready.
        // The JS side is idempotent — it tears down any prior observer first.
        if (HasMore && _module is not null)
        {
            _observer = await _module.InvokeAsync<IJSObjectReference>(
                "observe", _sentinelRef, _dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnIntersecting()
    {
        if (_isLoading || !HasMore)
            return;

        _isLoading = true;
        StateHasChanged();

        await OnLoadMore.InvokeAsync();

        _isLoading = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (_observer is not null)
        {
            try { await _observer.InvokeVoidAsync("disconnect"); }
            catch (JSDisconnectedException) { }
            try { await _observer.DisposeAsync(); }
            catch (JSDisconnectedException) { }
        }

        if (_module is not null)
        {
            try { await _module.DisposeAsync(); }
            catch (JSDisconnectedException) { }
        }

        _dotNetRef?.Dispose();
    }
}

export function observe(sentinel, dotNetRef) {
    const observer = new IntersectionObserver(entries => {
        for (const entry of entries) {
            if (entry.isIntersecting) {
                dotNetRef.invokeMethodAsync('OnIntersecting');
            }
        }
    }, { rootMargin: '0px 0px 200px 0px' });

    observer.observe(sentinel);
    return observer;
}

.infinite-scroll-container {
    overflow-y: auto;
}

.infinite-scroll-sentinel {
    display: flex;
    justify-content: center;
    padding: 1rem 0;
    min-height: 1px;
}

.infinite-scroll-spinner {
    width: 2rem;
    height: 2rem;
    border: 0.25rem solid currentColor;
    border-right-color: transparent;
    border-radius: 50%;
    animation: infinite-scroll-spin 0.75s linear infinite;
}

@keyframes infinite-scroll-spin {
    to { transform: rotate(360deg); }
}

